#include <stdio.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long col[1000] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            long long v;
            scanf("%lld", &v);
            col[j] += v;
        }
    }

    long long menor = col[0];

    for (int j = 1; j < M; j++) {
        if (col[j] < menor) {
            menor = col[j];
        }
    }

    printf("%lld\n", menor);
    return 0;
}
